/* Firmware images of the two internal 8 KiB MCUs of the SX1301, taken
 * verbatim from the Semtech reference HAL (lora_gateway, libloragw):
 *
 *   agc  - automatic gain control, version 4
 *   arb  - arbiter, version 1
 *   cal  - calibration, version 2.  Loaded into the AGC MCU before the
 *          production firmware, runs for about 2.3 s and then is replaced.
 *
 * They are const so that they live in flash rather than in RAM.
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include "sx1301_fw.h"

